#include <iostream>
using namespace std;

int fib(int n) {
    if (n <= 1)
        return n;
    return fib(n - 1) + fib(n - 2);
}

int main() {
    int n = 5;
    cout << fib(n);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int fib(int n, unordered_map<int, int>& memo) {
    if (memo.count(n)) {
        return memo[n]; // already computed — return instantly
    }
    if (n <= 1) {
        return n;
    }
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo); // compute once
    return memo[n]; // store and return
}

int main() {
    unordered_map<int, int> memo;
    cout << fib(5, memo);
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int fib(int n) {
    if (n == 0) return 0;

    vector<int> dp(n + 1, 0);
    dp[1] = 1; // base case

    for (int i = 2; i <= n; i++) {
        dp[i] = dp[i - 1] + dp[i - 2]; // fill left to right
    }

    return dp[n];
}

int main() {
    int n = 10;
    cout << fib(n) << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

int fib(int n) {
    if (n <= 1) return n;

    int a = 0, b = 1; // just two variables

    for (int i = 2; i <= n; i++) {
        int temp = a + b;
        a = b;
        b = temp; // slide forward
    }

    return b;
}

int main() {
    int n = 10;
    cout << fib(n) << endl;
    return 0;
}
